  {
    "content_key": "text_7370ced6e740b788c24cf892__ar",
    "locale": "ar",
    "section": "translations",
    "label": "Responsible for this website",
    "headline": "homepage_sections.legal_impressum.subheadline",
    "subheadline": null,
    "body": "المسؤول عن هذا الموقع",
