    "is_active": true
  },
  {
    "content_key": "text_f0991dc65619a1ee49352715__ar",
    "locale": "ar",
    "section": "translations",
    "label": "WorldOS is not a social network. It is not a think tank. It is a structured space for structured thinking — where the quality of the argument matters more than the volume of the voice.",
    "headline": "homepage_sections.about_cta.body",
    "subheadline": null,
    "body": "WorldOS ليس شبكة اجتماعية، ولا مركز أبحاث. إنه مساحة منظّمة للتفكير المنظّم، حيث تهمّ جودة الحجة أكثر من ارتفاع الصوت.",
    "media_url": null,
    "media_path": null,
    "display_order": 1157,
    "is_active": true
  },
  {
    "content_key": "text_ae45c3db2dbcfbd6ef28e0a8__ar",
